-- ── SELF-ASSERT ────────────────────────────────────────────────────────────────────────────────
do $$
declare
  r          public.sea_raster%rowtype;
  v_n        int;
  v_bad      int;
  v_ports    int;
  v_nm       numeric;
  v_ref      text;
  v_same     int;
  v_at_fixed int;
  v_elsewhere int;
  v_worst_nm  numeric;
  v_worst_pct numeric;
  v_lis_cad  constant jsonb := '[[38.71,-9.14],[36.875,-9.125],[36.625,-8.875],[36.53,-6.3]]'::jsonb;
  v_brs_ams  constant jsonb := '[[51.45,-2.6],[51.375,-4.625],[50.375,-5.625],[50.125,-5.875],[49.875,-5.625],[50.625,0.625],[53.125,4.625],[52.625,5.125],[52.37,4.88]]'::jsonb;
  -- the course the OLD raster served: Bristol straight across southern England to the Channel,
  -- then on to Amsterdam. It must now be refused as land.
  v_overland constant jsonb := '[[51.45,-2.6],[50.63,-0.13],[50.63,0.63],[52.37,4.88]]'::jsonb;
  -- the two courses this file exists for, over the water it opens…
  v_tok_nag  constant jsonb := '[[35.69,139.69],[34.875,139.875],[34.625,139.375],[30.875,130.875],[31.375,130.125],[32.75,129.88]]'::jsonb;
  v_pat_cag  constant jsonb := '[[38.25,21.73],[36.375,15.125],[37.375,12.375],[39.22,9.12]]'::jsonb;
  -- …and the two the game is serving RIGHT NOW, straight off findPath over the raster this file
  -- supersedes. Not drawn by hand: these are the exact polylines a client is given today, whose
  -- first leg walks out of the harbour across a peninsula on the strength of its snap.
  v_was_0    constant jsonb := '[[78.22,15.63],[70.875,30.625],[70.37,31.11]]'::jsonb;
  v_was_1    constant jsonb := '[[21.02,105.84],[15.88,108.33]]'::jsonb;
begin
  -- (a) THE RASTER IS THERE AND THE BIT ORDER IS THE ONE THE CLIENT PACKS. 45 control cells,
  --     each a named piece of the world, asserted through get_bit — the same read the sampler
  --     uses. A packing that shifted one bit would fail all of them.
  select * into r from public.sea_raster where id = 1;
  if r.cols <> 1440 or r.rows <> 720 or r.bits_per_cell <> 2 or octet_length(r.cells) <> 259200 then
    raise exception '0060 self-assert FAIL: the raster is % x % at % bit(s) with % bytes — expected 1440 x 720 at 2 with 259200', r.cols, r.rows, r.bits_per_cell, octet_length(r.cells);
  end if;
  if get_bit(r.cells, 692320) <> 1 then
    raise exception '0060 self-assert FAIL: the mid-Atlantic (30, -40) reads %, expected 1', get_bit(r.cells, 692320);
