  -- (a3) THE THIRTY-NINE. Every harbour that snapped over 20 nm on the raster this file
  --      supersedes now snaps at or under it — AND the check reads BOTH numbers, so it cannot
  --      pass vacuously: a world where the defect never existed fails the first half.
  select count(*) into v_n from _0060_before where snap_nm > 20;
  if v_n <> 40 then
    raise exception '0060 self-assert FAIL: the raster being superseded had % harbour(s) snapping over 20 nm, expected 40 — this file was cut against a different sea', v_n;
  end if;
  select count(*) into v_bad
    from _0060_before b join public.sea_reaches a on a.code = b.code
   where b.snap_nm > 20 and a.snap_nm > 20;
  if v_bad <> 0 then
    raise exception '0060 self-assert FAIL: % harbour(s) still snap over 20 nm to sailable water — they keep a land-exempt corridor across their own country (%)', v_bad,
      (select string_agg(a.code || ' ' || round(a.snap_nm, 2), ', ' order by a.snap_nm desc)
         from _0060_before b join public.sea_reaches a on a.code = b.code
        where b.snap_nm > 20 and a.snap_nm > 20);
  end if;
  select count(*) into v_bad from public.sea_reaches where snap_nm > 20;
  if v_bad <> 0 then
    raise exception '0060 self-assert FAIL: % harbour(s) snap over 20 nm', v_bad;
  end if;
  -- …and NOTHING ELSE moved. A snap that changed at a harbour that was already inside the
  --   threshold would mean a channel ran somewhere nobody asked it to.
  select count(*) into v_bad
    from _0060_before b join public.sea_reaches a on a.code = b.code
   where b.snap_nm <= 20 and abs(a.snap_nm - b.snap_nm) > 0.005;
  if v_bad <> 0 then
    raise exception '0060 self-assert FAIL: % harbour(s) this file never set out to touch had their snap moved', v_bad;
  end if;

  -- (a4) EVERY ONE OF THE 40, BY NAME AND BY NUMBER. The list above proves the property; this
  --      proves the file was cut against the sea it says it was, harbour by harbour.
  if (select snap_nm from _0060_before where code = 'LNG') is distinct from 67.68
     or (select snap_nm from public.sea_reaches where code = 'LNG') is distinct from 0.00 then
    raise exception '0060 self-assert FAIL: LNG (Longyearbyen) should have gone 67.68 -> 0.00 nm, went [%] -> [%]',
      coalesce((select snap_nm::text from _0060_before where code = 'LNG'), 'null'),
      coalesce((select snap_nm::text from public.sea_reaches where code = 'LNG'), 'null');
  end if;
  if (select snap_nm from _0060_before where code = 'HAN') is distinct from 58.68
     or (select snap_nm from public.sea_reaches where code = 'HAN') is distinct from 0.00 then
    raise exception '0060 self-assert FAIL: HAN (Hanoi) should have gone 58.68 -> 0.00 nm, went [%] -> [%]',
      coalesce((select snap_nm::text from _0060_before where code = 'HAN'), 'null'),
      coalesce((select snap_nm::text from public.sea_reaches where code = 'HAN'), 'null');
